// Deterministic synthetic Q8_0 Qwen4-Exp fixture, not trained language weights.
// Generated by Nix so tests never download a production checkpoint.
use std::{
    error::Error,
    fs,
    io::{BufWriter, Write},
    path::Path,
};

struct Tensor {
    name: String,
    dims: Vec<u64>,
    ty: u32,
    pattern: u8,
}
fn string(out: &mut Vec<u8>, value: &str) {
    out.extend((value.len() as u64).to_le_bytes());
    out.extend(value.as_bytes());
}
fn main() -> Result<(), Box<dyn Error>> {
    let path = std::env::args_os()
        .nth(1)
        .ok_or("output GGUF path required")?;
    let mut tensors = Vec::new();
    let mut add = |name: &str, dims: &[u64], ty: u32, pattern: u8| {
        tensors.push(Tensor {
            name: name.into(),
            dims: dims.into(),
            ty,
            pattern,
        })
    };
    add("token_embd.weight", &[64, 248320], 8, 1);
    add("output.weight", &[64, 248320], 8, 2);
    add("output_norm.weight", &[64], 0, 1);
    for prefix in ["output_hc_", "blk.0.hc_attn_", "blk.0.hc_ffn_"] {
        add(&format!("{prefix}norm.weight"), &[128], 0, 1);
        add(&format!("{prefix}down.weight"), &[128, 64], 8, 0);
        add(&format!("{prefix}up.weight"), &[64, 128], 8, 0);
        if prefix != "output_hc_" {
            add(&format!("{prefix}inject.weight"), &[128, 2], 8, 0);
        }
    }
    for (suffix, dims, pattern) in [
        ("attn_q.weight", vec![64, 128], 0),
        ("attn_k.weight", vec![64, 64], 0),
        ("attn_v.weight", vec![64, 64], 3),
        ("attn_output.weight", vec![64, 64], 3),
        ("ffn_gate_inp.weight", vec![64, 2], 0),
        ("ffn_gate_exps.weight", vec![64, 64, 2], 0),
        ("ffn_up_exps.weight", vec![64, 64, 2], 0),
        ("ffn_down_exps.weight", vec![64, 64, 2], 0),
        ("ffn_gate_shexp.weight", vec![64, 64], 0),
        ("ffn_up_shexp.weight", vec![64, 64], 0),
        ("ffn_down_shexp.weight", vec![64, 64], 0),
        ("ffn_gate_inp_shexp.weight", vec![64, 1], 0),
    ] {
        add(&format!("blk.0.{suffix}"), &dims, 8, pattern);
    }
    for suffix in ["attn_q_norm.weight", "attn_k_norm.weight"] {
        add(&format!("blk.0.{suffix}"), &[64], 0, 1);
    }
    let metadata = [
        ("block_count", 1),
        ("context_length", 2048),
        ("embedding_length", 64),
        ("attention.head_count", 1),
        ("attention.head_count_kv", 1),
        ("attention.key_length", 64),
        ("full_attention_interval", 1),
        ("expert_count", 2),
        ("expert_used_count", 1),
        ("expert_feed_forward_length", 64),
        ("expert_shared_feed_forward_length", 64),
        ("hyper_connection.count", 2),
        ("hyper_connection.low_rank", 64),
    ];
    let mut header = Vec::new();
    header.extend(b"GGUF");
    header.extend(3_u32.to_le_bytes());
    header.extend((tensors.len() as u64).to_le_bytes());
    header.extend((metadata.len() as u64 + 2).to_le_bytes());
    string(&mut header, "general.architecture");
    header.extend(8_u32.to_le_bytes());
    string(&mut header, "qwen4exp");
    for (key, value) in metadata {
        string(&mut header, &format!("qwen4exp.{key}"));
        header.extend(4_u32.to_le_bytes());
        header.extend((value as u32).to_le_bytes());
    }
    string(&mut header, "qwen4exp.attention.layer_norm_rms_epsilon");
    header.extend(6_u32.to_le_bytes());
    header.extend(1e-6_f32.to_le_bytes());
    let mut offset = 0_u64;
    for tensor in &tensors {
        string(&mut header, &tensor.name);
        header.extend((tensor.dims.len() as u32).to_le_bytes());
        for dim in &tensor.dims {
            header.extend(dim.to_le_bytes());
        }
        header.extend(tensor.ty.to_le_bytes());
        header.extend(offset.to_le_bytes());
        let elements: u64 = tensor.dims.iter().product();
        let bytes = if tensor.ty == 0 {
            elements * 4
        } else {
            elements / 32 * 34
        };
        offset = (offset + bytes).next_multiple_of(32);
    }
    header.resize(header.len().next_multiple_of(32), 0);
    let mut output = BufWriter::new(fs::File::create(Path::new(&path))?);
    output.write_all(&header)?;
    for tensor in tensors {
        let elements: u64 = tensor.dims.iter().product();
        let mut written = 0;
        if tensor.ty == 0 {
            for _ in 0..elements {
                output.write_all(&(tensor.pattern as f32).to_le_bytes())?;
                written += 4;
            }
        } else {
            let columns = tensor.dims[0];
            let rows = elements / columns;
            for row in 0..rows {
                for block in 0..columns / 32 {
                    output.write_all(&0x3c00_u16.to_le_bytes())?;
                    let mut bytes = [0_u8; 32];
                    for (i, value) in bytes.iter_mut().enumerate() {
                        let col = block * 32 + i as u64;
                        *value = match tensor.pattern {
                            1 => {
                                if row == 1 && col == 0 {
                                    2
                                } else if row == 2 && col == 1 {
                                    3
                                } else {
                                    1
                                }
                            }
                            2 => u8::from(row == 42),
                            3 => u8::from(row == col),
                            _ => 0,
                        };
                    }
                    output.write_all(&bytes)?;
                    written += 34;
                }
            }
        }
        let padding = (32 - written % 32) % 32;
        output.write_all(&vec![0; padding])?;
    }
    output.flush()?;
    Ok(())
}
